import{bV as a,aL as n,u as s,G as e}from"./chunks/framework.DT-LCgF3.js";const u=JSON.parse('{"title":"ICMP","description":"","frontmatter":{"date":"2026-08-05T16:10:00.000Z","title":"ICMP","permalink":"/pages/2d3e4f","categories":["Protocol","网络层协议"]},"headers":[],"relativePath":"Protocol/03.网络层协议/01.icmp.md","filePath":"Protocol/03.网络层协议/01.icmp.md","lastUpdated":1785924051000}'),r={name:"Protocol/03.网络层协议/01.icmp.md"};function o(l,t,i,d,p,c){return n(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="icmp-协议" tabindex="-1">ICMP 协议 <a class="header-anchor" href="#icmp-协议" aria-label="Permalink to &quot;ICMP 协议&quot;">​</a></h1><p>ICMP（Internet Control Message Protocol，<strong>网际控制报文协议</strong>）是 <strong>TCP/IP 网络层（OSI 第三层）</strong> 的协议，IP 协议号 <strong>1</strong>。它<strong>不传输用户业务数据</strong>，而是用于在 IP 主机、路由器之间传递<strong>控制与差错信息</strong>，是「网络自我诊断」的工具。</p><blockquote><p>注意：ICMP <strong>不是传输层协议</strong>，它和 TCP/UDP 是「同层邻居」——都基于 IP，但职责不同。我们平时用的 <code>ping</code>、<code>traceroute</code> 就是建立在 ICMP 之上的。</p></blockquote><hr><h2 id="一、icmp-的作用" tabindex="-1">一、ICMP 的作用 <a class="header-anchor" href="#一、icmp-的作用" aria-label="Permalink to &quot;一、ICMP 的作用&quot;">​</a></h2><ol><li><strong>差错报告</strong>：当 IP 包无法送达或处理异常时，由路由器/主机回送差错报文。 <ul><li>目的不可达（网络/主机/端口/协议不可达）</li><li>超时（TTL 减到 0，或分片重组超时）</li><li>参数问题（首部字段错误）</li></ul></li><li><strong>查询/诊断</strong>（典型就是 ping / traceroute）： <ul><li><strong>回送请求 / 回送应答（Echo）</strong>：ping 的原理。</li><li><strong>时间戳请求 / 应答</strong>：测量往返时间。</li><li><strong>地址掩码请求 / 应答</strong>：获取子网掩码（现已少用）。</li></ul></li></ol><hr><h2 id="二、报文格式" tabindex="-1">二、报文格式 <a class="header-anchor" href="#二、报文格式" aria-label="Permalink to &quot;二、报文格式&quot;">​</a></h2><p>ICMP 报文封装在 IP 数据报中（IP 首部 protocol=1，后面跟 ICMP 报文）：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 0               1               2               3</span></span>
<span class="line"><span> 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|  类型 Type  |  代码 Code  |           校验和 Checksum         |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|              根据不同的 Type/Code 携带的附加信息            |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                          数据 ...                          |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><ul><li><strong>类型（Type）</strong>：区分报文种类（如 0=回送应答，8=回送请求，3=目的不可达，11=超时）。</li><li><strong>代码（Code）</strong>：在同一类型下细分（如目的不可达的 网络/主机/端口 不可达）。</li><li><strong>校验和</strong>：覆盖整个 ICMP 报文。</li></ul><p>常见类型速查：</p><table tabindex="0"><thead><tr><th>Type</th><th>含义</th><th>典型用途</th></tr></thead><tbody><tr><td>0 / 8</td><td>回送应答 / 回送请求</td><td>ping</td></tr><tr><td>3</td><td>目的不可达</td><td>路由/端口不可达报错</td></tr><tr><td>11</td><td>超时（TTL=0 / 重组超时）</td><td>traceroute</td></tr><tr><td>5</td><td>重定向</td><td>通知更优路由</td></tr></tbody></table><hr><h2 id="三、典型应用" tabindex="-1">三、典型应用 <a class="header-anchor" href="#三、典型应用" aria-label="Permalink to &quot;三、典型应用&quot;">​</a></h2><h3 id="ping" tabindex="-1">ping <a class="header-anchor" href="#ping" aria-label="Permalink to &quot;ping&quot;">​</a></h3><p>发送 <strong>ICMP Echo Request（Type 8）</strong>，对端回 <strong>Echo Reply（Type 0）</strong>。通过统计往返时间（RTT）和丢包率判断连通性与网络质量。</p><h3 id="traceroute-windows-tracert" tabindex="-1">traceroute（Windows: tracert） <a class="header-anchor" href="#traceroute-windows-tracert" aria-label="Permalink to &quot;traceroute（Windows: tracert）&quot;">​</a></h3><p>利用 <strong>TTL</strong> 机制：逐跳把 IP 包的 TTL 设为 1, 2, 3…，每经过一跳路由器 TTL 减 1，减到 0 时路由器丢弃该包并返回 <strong>ICMP 超时报文（Type 11）</strong>，从而暴露每一跳的地址，画出路径。</p><hr><h2 id="四、与-tcp-udp-的区别" tabindex="-1">四、与 TCP/UDP 的区别 <a class="header-anchor" href="#四、与-tcp-udp-的区别" aria-label="Permalink to &quot;四、与 TCP/UDP 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>ICMP</th><th>TCP / UDP</th></tr></thead><tbody><tr><td>所属层</td><td>网络层（L3）</td><td>传输层（L4）</td></tr><tr><td>是否传用户数据</td><td>否（仅控制/诊断）</td><td>是</td></tr><tr><td>是否有端口号</td><td>否</td><td>是</td></tr><tr><td>典型应用</td><td>ping / traceroute / 差错报告</td><td>网页、文件、音视频等</td></tr></tbody></table><hr><h2 id="五、注意事项" tabindex="-1">五、注意事项 <a class="header-anchor" href="#五、注意事项" aria-label="Permalink to &quot;五、注意事项&quot;">​</a></h2><ul><li>ICMP 常被<strong>防火墙限制或丢弃</strong>（尤其 Echo 类型），所以 <code>ping 不通</code> 不代表服务不可达（TCP 端口可能仍开放）。</li><li>不要滥用 ICMP（如大量 Echo 请求构成 ping flood 攻击）；生产环境常对 ICMP 速率做限制。</li><li>ICMP 本身不可靠，差错报文也可能丢失，不应作为唯一的可靠性依据。</li></ul>`,25)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
